import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { normalizeHeadword, type LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { Button } from '@/components/ui/Button.js';
import { Icon } from '@/components/ui/Icon.js';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { read as readApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { ProOffer } from '@/features/billing/ProOffer.js';
import { proHere, useBilling } from '@/features/billing/state.js';
import { getActiveNotebook, listNotebooks, listWords } from '@/db/repo.js';
import { importWords, type ImportRow } from '@/db/mutations.js';
import { NewNotebookSheet } from '@/features/notebook/NewNotebookSheet.js';
import { NotebookRoute } from '@/features/notebook/NotebookRoute.js';
import { routeFor, settles } from '@/features/notebook/route.js';
import type { StoredNotebook } from '@/db/schema.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { localTimeZone } from '@/lib/format.js';
import { useTextLimits } from '@/lib/useConfig.js';
import { syncSoon } from '@/sync/store.js';
import { notePasteUse } from '@/features/everywhere/state.js';
import { cx } from '@/lib/cx.js';
import { t } from '@/i18n/index.js';
import type { ApiTerm } from '@/api/types.js';
import styles from './Read.module.css';

/**
 * Reading something the learner has just read, and marking what is worth
 * keeping out of it.
 *
 * This is not the app supplying vocabulary. The text is theirs — an article,
 * a message, a page of a book — and what comes back was already in front of
 * them. What the model adds is judgement about which parts of it are worth a
 * card, which is exactly the thing a reader cannot do for the language they
 * are still learning: the words you need are rarely the ones you notice.
 *
 * Everything found is kept by default and struck through by tapping, because
 * the list is a suggestion to prune rather than a form to fill in. Words
 * already in the notebook never appear at all; they are counted instead, so
 * the number still adds up.
 */
export function Read(): React.JSX.Element {
  const navigate = useNavigate();
  const [text, setText] = useState('');
  const [busy, setBusy] = useState(false);
  const [found, setFound] = useState<ApiTerm[] | undefined>();
  const [already, setAlready] = useState(0);
  const [dropped, setDropped] = useState<ReadonlySet<string>>(new Set());
  const [failed, setFailed] = useState('');
  const [offering, setOffering] = useState(false);
  const [adding, setAdding] = useState(false);

  const active = useLiveQuery(getActiveNotebook, undefined, []);
  const notebooks = useLiveQuery(() => listNotebooks(), undefined, []);
  const limits = useTextLimits();
  const [picked, setPicked] = useState<StoredNotebook | undefined>();
  const [making, setMaking] = useState<{ language: LanguageCode | undefined } | undefined>();

  // A paragraph is the easiest thing there is to place: the script settles
  // it, and a text in a language none of the notebooks holds is worth
  // saying so before a word of it is read.
  const all = notebooks ?? [];
  const destination = routeFor(text, all, active);
  const notebook = picked ?? settles(destination, active) ?? active;
  const billing = useBilling((state) => state.state);
  const ensurePlan = useBilling((state) => state.ensure);
  const refreshPlan = useBilling((state) => state.refresh);
  ensurePlan();

  const look = (): void => {
    const prose = text.trim();
    if (prose === '' || notebook === undefined) return;
    if (prose.length < MIN_TEXT) {
      setFailed(t('read.tooShort'));
      return;
    }
    // The server decides this too, and its answer is what counts. Asking
    // here as well means somebody on the free plan is offered the plan
    // instead of watching a spinner end in a refusal -- with the same
    // exemption the server applies, so a notebook Lexpad never charges for
    // is not stopped here by a rule the API would not have enforced.
    if (!proHere(billing, notebook.targetLang, notebook.meaningLang)) {
      setOffering(true);
      return;
    }
    setBusy(true);
    setFailed('');
    setOffering(false);
    readApi
      .text(notebook.id, prose)
      .then(async (out) => {
        const mine = new Set((await listWords(notebook.id)).map((word) => normalizeHeadword(word.headword)));
        const fresh = out.terms.filter((term) => !mine.has(normalizeHeadword(term.text)));
        setAlready(out.terms.length - fresh.length);
        setFound(fresh);
        setDropped(new Set());
      })
      .catch((cause: unknown) => {
        if (isApiError(cause, 'needsPayment')) {
          // The server is the authority on this, and it has just disagreed
          // with what this device believed. Read the plan again before
          // offering it, or the offer renders as nothing at all: it is
          // deliberately silent for an account it thinks is already paying.
          void refreshPlan().finally(() => {
            setOffering(true);
          });
          return;
        }
        setFailed(isApiError(cause, 'offline') ? t('error.offline') : t('read.failed'));
      })
      .finally(() => {
        setBusy(false);
      });
  };

  const keep = (terms: readonly ApiTerm[]): void => {
    if (notebook === undefined) return;
    const rows: ImportRow[] = terms
      .filter((term) => !dropped.has(term.text))
      .map((term) => ({
        ref: term.text,
        word: {
          headword: term.text,
          category: 'general',
          source: 'ai',
          ...(term.level === undefined ? {} : { level: term.level }),
          ...(term.kind === 'phrase' ? { pos: 'phrase' } : {}),
          // The sentence it was met in becomes the card's example, which is
          // the whole reason it is worth more than the same word off a list.
          meanings: [
            {
              meaning: term.meaning,
              examples: term.sentence === undefined ? [] : [{ sentence: term.sentence }],
            },
          ],
          expressions: [],
          collocations: [],
          relatedWords: [],
          relatedWordIds: [],
        },
        relatedRefs: [],
      }));
    if (rows.length === 0) return;
    setAdding(true);
    void importWords(notebook.id, rows, localTimeZone())
      .then(() => notePasteUse())
      .then(() => syncSoon())
      .then(() => navigate('/notebook'))
      .catch(() => {
        setAdding(false);
        setFailed(t('read.failed'));
      });
  };

  const kept = found?.filter((term) => !dropped.has(term.text)).length ?? 0;

  if (making !== undefined) {
    return (
      <NewNotebookSheet
        {...(making.language === undefined ? {} : { startAt: making.language })}
        onCreated={(made) => {
          setMaking(undefined);
          const fresh = all.find((one) => one.id === made);
          if (fresh !== undefined) setPicked(fresh);
        }}
        onClose={() => {
          setMaking(undefined);
        }}
      />
    );
  }

  return (
    <main className={styles.screen}>
      <header className={styles.head}>
        <button
          type="button"
          className={styles.back}
          aria-label={t('action.back')}
          onClick={() => {
            void navigate('/');
          }}
        >
          <Icon name="chevronLeft" size={20} weight={2} />
        </button>
        <h1 className={styles.title}>{t('read.title')}</h1>
      </header>

      {found === undefined ? (
        <>
          {/* A heading of its own, because the toolbar title is small and
              this screen has to say what it is for before somebody pastes
              five hundred words into it. */}
          <h2 className={styles.ask}>{t('read.ask')}</h2>
          <p className={styles.lead}>{t('read.lead')}</p>
          {/* The label is a real one rather than the placeholder doing two
              jobs: a placeholder disappears the moment anybody types, and
              it was the only thing naming this field. */}
          <label className={styles.field}>
            <span className={styles.fieldLabel}>{t('read.fieldLabel')}</span>
            <textarea
              className={styles.input}
              value={text}
              dir="auto"
              rows={9}
              maxLength={limits.read}
              placeholder={t('read.placeholder')}
              autoFocus
              onChange={(event) => {
                setText(event.target.value);
                setFailed('');
              }}
            />
            <span className={styles.fieldCount}>
              {text.trim() === '' ? '' : t('read.characters', { count: text.length })}
            </span>
          </label>
          {text.length >= limits.read && <p className={styles.note}>{t('read.long')}</p>}

          <NotebookRoute
            destination={destination}
            chosen={notebook}
            onChoose={setPicked}
            onMake={(language) => {
              setMaking({ language });
            }}
          />
          {failed !== '' && <p className={styles.failed}>{failed}</p>}

          {offering ? (
            <div className={styles.offer}>
              <ProOffer
                occasion="readText"
                about={
                  notebook === undefined
                    ? undefined
                    : { targetLang: notebook.targetLang, meaningLang: notebook.meaningLang }
                }
              />
            </div>
          ) : (
            <Button
              block
              size="large"
              busy={busy}
              disabled={text.trim() === '' || notebook === undefined}
              onClick={look}
            >
              {busy ? t('read.reading') : t('read.go')}
            </Button>
          )}

          {/* Part of the same set as the primary action rather than an
              underlined link floating below it. */}
          <Button
            variant="secondary"
            block
            onClick={() => {
              void navigate('/ai');
            }}
          >
            {t('read.haveAList')}
          </Button>
        </>
      ) : found.length === 0 ? (
        <EmptyState
          icon="sparkles"
          tone="quiet"
          title={t('read.nothingTitle')}
          body={
            already > 0
              ? `${t('read.nothing')} ${already === 1 ? t('read.alreadyOne') : t('read.already', { count: already })}`
              : t('read.nothing')
          }
          actions={
            <Button variant="secondary" onClick={startOver(setFound, setText)}>
              {t('read.again')}
            </Button>
          }
        />
      ) : (
        <>
          <p className={styles.lead}>
            {found.length === 1 ? t('read.foundOne') : t('read.found', { count: found.length })}
          </p>
          {/* How many are currently kept, which is the number the button at
              the bottom will act on. A count, not a progress bar: choosing
              six of seven words is not six sevenths of anything. */}
          <p className={styles.selected} role="status">
            {t('read.selected', { count: kept })}
          </p>
          <ul className={styles.terms}>
            {found.map((term) => {
              const on = !dropped.has(term.text);
              return (
                <li key={term.text}>
                  <button
                    type="button"
                    className={cx(styles.term, !on && styles.termOff)}
                    aria-pressed={on}
                    onClick={() => {
                      setDropped((previous) => {
                        const next = new Set(previous);
                        if (next.has(term.text)) next.delete(term.text);
                        else next.add(term.text);
                        return next;
                      });
                    }}
                  >
                    <span className={styles.termHead}>
                      <Bilingual lang={notebook?.targetLang ?? 'en'} className={styles.termText}>
                        {term.text}
                      </Bilingual>
                      {term.kind === 'phrase' && <span className={styles.tag}>{t('read.phrase')}</span>}
                      {term.level !== undefined && <span className={styles.tag}>{term.level}</span>}
                      {/* Kept or not, said by a shape as well as by the
                          card's tint: a strike-through alone is hard to see
                          on a phone in daylight. */}
                      <span className={cx(styles.check, on && styles.checkOn)} aria-hidden="true">
                        {on && <Icon name="check" size={14} weight={2.6} />}
                      </span>
                    </span>
                    <Bilingual lang={notebook?.meaningLang ?? 'en'} className={styles.termMeaning}>
                      {term.meaning}
                    </Bilingual>
                    {term.sentence !== undefined && (
                      <Bilingual lang={notebook?.targetLang ?? 'en'} className={styles.termSentence}>
                        {term.sentence}
                      </Bilingual>
                    )}
                  </button>
                </li>
              );
            })}
          </ul>
          {already > 0 && (
            <p className={styles.note}>
              {already === 1 ? t('read.alreadyOne') : t('read.already', { count: already })}
            </p>
          )}
          {failed !== '' && <p className={styles.failed}>{failed}</p>}

          <div className={styles.foot}>
            <Button
              block
              size="large"
              busy={adding}
              disabled={kept === 0}
              onClick={() => {
                keep(found);
              }}
            >
              {kept === 0 ? t('read.none') : kept === 1 ? t('read.addOne') : t('read.add', { count: kept })}
            </Button>
            <Button variant="secondary" block onClick={startOver(setFound, setText)}>
              {t('read.again')}
            </Button>
          </div>
        </>
      )}
    </main>
  );
}

/**
 * The shortest text worth sending. The longest is the server's to say and
 * is read through useTextLimits; this one is not, because below it there is
 * nothing for a model to read whatever anybody configures.
 */
const MIN_TEXT = 20;

/** Back to an empty page, for the two places that offer it. */
function startOver(
  setFound: (terms: ApiTerm[] | undefined) => void,
  setText: (text: string) => void,
): () => void {
  return () => {
    setFound(undefined);
    setText('');
  };
}
